const express = require('express');
const { query, validationResult } = require('express-validator');
const axios = require('axios');
const knex = require('knex')({ client: 'pg', connection: process.env.DB_URL });

const app = express();

const latencyMetricsValidation = [
  query('serviceKey').isString().matches(/^[a-z0-9-_]{3,32}$/).withMessage('Invalid serviceKey format'),
  query('window').isIn(['5m', '15m', '1h', '24h']).withMessage('Invalid time window')
];

app.get('/api/apm/services/latency', latencyMetricsValidation, async (req, res) => {
  if (!req.user || !req.user.teamId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { serviceKey, window } = req.query;

  // Verify that caller's team has access to the target service
  const serviceAccess = await knex('services')
    .where({ key: serviceKey, owning_team_id: req.user.teamId })
    .first();

  if (!serviceAccess) {
    return res.status(403).json({ error: 'Forbidden: unauthorized service metrics' });
  }

  const prometheusResponse = await axios.get('http://metrics-internal:9090/api/v1/query', {
    params: {
      query: `histogram_quantile(0.99, sum(rate(http_request_duration_seconds_bucket{service="${serviceKey}"}[${window}])) by (le))`
    }
  });

  res.json({ service: serviceKey, metrics: prometheusResponse.data });
});

app.listen(6004);
